// Loop over input items and add a new field called 'myNewField' to the JSON of each one
let allPages = ''

for (const item of $input.all()) {
  allPages += item.json.text
}

let pagesArr = allPages.split('Danfe Pack V 2.6.0 nfstock | Alterdata Software\n\n')

return pagesArr.map(page => ({ json: { pagina: page } }))
